/** Fetches every runtime asset not cached yet (4 at a time), telling the open pages how far it got. */
let warming = null;
function warm() {
  if (warming) return warming;
  warming = (async () => {
    const cache = await caches.open(CACHE);
    let done = 0;
    let failed = 0;
    const tell = async () => {
      for (const c of await self.clients.matchAll({ includeUncontrolled: true })) c.postMessage({ type: 'offline-progress', done, failed, total: WARM.length });
    };
    const queue = WARM.slice();
    const lane = async () => {
      for (let url = queue.shift(); url; url = queue.shift()) {
        try {
          if (!(await cache.match(url, { ignoreSearch: true, ignoreVary: true }))) {
            const res = await fetch(new Request(url, { cache: 'reload' }));
            if (res.ok) await cache.put(url, res);
            else failed++;
          }
        } catch {
          failed++;
        }
        done++;
        if (done % 8 === 0 || done === WARM.length) await tell();
      }
    };
    await tell();
    await Promise.all([lane(), lane(), lane(), lane()]);
    await tell();
    warming = null;
  })();
  return warming;
}

